<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1" />
<title>Bookmarks — prototype</title>
<style>
  * { box-sizing: border-box; }
  body {
    font-family: -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
    margin: 0; background: #f5f6f8; color: #1c2330;
  }
  header {
    background: #fff; border-bottom: 1px solid #e3e6ea;
    padding: 18px 20px;
  }
  header h1 { margin: 0; font-size: 20px; }
  header p { margin: 4px 0 0; color: #6b7480; font-size: 13px; }
  li.card .titlerow { display: flex; align-items: center; gap: 8px; }
  li.card .editbtn {
    border: 1px solid #cfd4da; background: #fff; color: #56606d;
    border-radius: 6px; font-size: 12px; padding: 3px 9px; cursor: pointer;
  }
  li.card .editbtn:hover { background: #f0f2f5; }
  li.card .titleedit {
    flex: 1; font-size: 15px; padding: 6px 8px; border: 1px solid #2f6fed;
    border-radius: 6px;
  }
  .fetching { color: #94a0ad; font-style: italic; }
  .tags { margin-top: 10px; display: flex; flex-wrap: wrap; gap: 6px; align-items: center; }
  .tag {
    background: #eef3ff; color: #2f5fd0; border-radius: 999px;
    font-size: 12px; padding: 3px 10px 3px 11px; display: inline-flex; gap: 6px; align-items: center;
  }
  .tag .x { cursor: pointer; color: #7a92c7; font-weight: 700; }
  .tag .x:hover { color: #c0392b; }
  .tagadd {
    border: 1px dashed #cfd4da; background: #fff; color: #56606d;
    border-radius: 999px; font-size: 12px; padding: 3px 12px; cursor: pointer;
  }
  .tagadd:hover { background: #f0f2f5; }
  .taginput {
    font-size: 12px; padding: 3px 8px; border: 1px solid #2f6fed;
    border-radius: 999px; width: 120px;
  }
  .tagwrap { position: relative; display: inline-block; }
